<?php use App\Support\App;$u=App::requireAuth();$title='Support';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><h1 class="page-title">Support</h1><p class="page-sub">Butuh bantuan? Buat tiket dan jelaskan kendala Anda.</p><form id="ticket" class="saas-card p-5 sm:p-6 mt-6 max-w-2xl space-y-4"><input type="hidden" id="csrf" value="<?=App::csrf()?>"><div><label class="text-sm font-semibold">Subject</label><input class="field mt-2" name="subject" placeholder="Contoh: Order masih processing" required></div><div><label class="text-sm font-semibold">Message</label><textarea class="field mt-2 min-h-36" name="message" placeholder="Jelaskan kendala secara lengkap..." required></textarea></div><button class="btn btn-dark"><i data-lucide="send"></i>Send ticket</button></form><script>ticket.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/tickets',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:JSON.stringify(Object.fromEntries(new FormData(ticket)))}),j=await r.json();Swal.fire(j.ok?'Ticket created':'Error',j.message||'Request diproses',j.ok?'success':'error')}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>